mapper.select:
select t.person_name,t.person_name personName,t.machine_id,t.machine_id machineId,t.person_id,t.person_id
personId,t.status_cd,t.status_cd statusCd,t.lmo_id,t.lmo_id lmoId,t.type,t.operation_time,t.operation_time
operationTime, t.create_time createTime, lm.machine_name machineName, td.name typeName
from lamp_machine_operation t
left join lamp_machine lm on t.machine_id = lm.machine_id and lm.status_cd = '0'
left join t_dict td on t.type = td.status_cd and td.table_name = 'lamp_machine_operation' and td.table_columns = 'type'
where 1 =1

    and t.person_name= #{personName}


    and t.machine_id= #{machineId}


    and t.person_id= #{personId}


    and t.status_cd= #{statusCd}


    and t.lmo_id= #{lmoId}


    and t.type= #{type}


    and t.operation_time= #{operationTime}


    and t.create_time >= #{queryStartTime}


    and t.create_time <= #{queryEndTime}

order by t.create_time desc

    limit #{page}, #{row}

